import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; k++) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(16, 16);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, 
                  (N + block_size.y - 1) / block_size.y);

    matrix_mult_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 N);
    return C;
}
"""

