                }
            }
        }

        __syncthreads();
    }

    // Write results
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    if (row < N && col < N) {
        C[row * N + col] = sum[0][0];
    }

    if (row < N && col + 16 < N) {
        C[row * N + (col + 16)] = sum[0][1];
    }

    if (row + 16 < N && col < N) {
        C[(row + 16) * N + col] = sum[1][0];
    }

    if (row + 16 < N && col + 16 < N) {
        C[(row + 16) * N + (col + 16)] = sum[1][1];
    }
